classes.Conflict = errors.define({
  tag = "Conflict",
  categories = { "ConflictError" },
  matchers = { { status = 409 } },
  fields = { "details" },
})
classes.Forbidden = errors.define({
  tag = "Forbidden",
  categories = { "AuthError" },
  matchers = { { status = 403 } },
  fields = { "details" },
})
classes.NotFound = errors.define({
  tag = "NotFound",
  categories = { "BadRequestError" },
  matchers = { { status = 404 } },
  fields = { "details" },
})
classes.SacRealmNotPaired = errors.define({
  tag = "SacRealmNotPaired",
  categories = { "BadRequestError" },
  matchers = { { status = 400, message = { includes = "must be attached to a partner realm" } } },
  fields = { "details" },
})

